"""Export authored synth parts on the render beat axis without writing audio."""

import argparse
import json
from collections import Counter
from pathlib import Path

from synth_tracks import ScoreSource, moonlight_waltz, neon_run, robot_parade, rooftop_swing

TARGET = Path(__file__).resolve().parents[2] / "src/content/synthScores.generated.ts"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the generated export is stale")
    args = parser.parse_args()

    lines = [
        "// Generated by tools/music/export_synth_scores.py; do not edit.",
        "export const synthScores: Record<string, readonly (readonly [",
        "  beat: number, duration: number, midi: number | null, role: 'pulse' | 'bass' | 'lead' | 'rhythm',",
        "])[]> = {",
    ]
    counts = []
    for render in (neon_run, robot_parade, rooftop_swing, moonlight_waltz):
        events: list[ScoreSource] = []
        track = render(events)
        lines.append(f"  {json.dumps(track.id)}: [")
        lines.extend(f"    {json.dumps(event)}," for event in sorted(events, key=lambda event: (event[0], event[3])))
        lines.append("  ],")
        roles = Counter(event[3] for event in events)
        breakdown = ", ".join(f"{role}={roles[role]}" for role in ("pulse", "bass", "lead", "rhythm"))
        counts.append(f"{track.id}: {len(events)} source events ({breakdown})")

    data = "\n".join([*lines, "};", ""])
    if args.check:
        if not TARGET.exists() or TARGET.read_text(encoding="utf-8") != data:
            raise SystemExit("Synth score export is stale; run tools/music/export_synth_scores.py")
    else:
        TARGET.write_text(data, encoding="utf-8", newline="\n")
    print(*counts, sep="\n")


if __name__ == "__main__":
    main()
